  Lemma aobj_prepare_rel : forall s LB m LF m1 FB n LB' FB' s' m' a k,
    as_RHEAP H s LB m -> as_RFS H LF m1 -> fb_prepare_rel H LB FB n LB' FB' -> as_RHEAP H s' LB' m' -> aobj LB LF a k -> 0 < k ->
    (a + k <= fb_begin FB \/ fb_end FB <= a) ->
    aobj LB' LF a k /\ (a + k <= fb_begin FB' \/ fb_end FB' <= a).
  Proof.
    intros s LB m LF m1 FB n LB' FB' s' m' a k RH RF REL RH' AO Hk D. unfold fb_prepare_rel in REL.
    destruct (fb_prep_inplace FB n || fb_prep_slide FB n) eqn:PS.
    { destruct REL as [-> ->]. split; [exact AO|]. unfold fb_prep_small. destruct (fb_prep_inplace FB n); cbn [fb_begin fb_end]; exact D. }
    destruct REL as (p' & A' & _ & -> & ALT). unfold fb_prep_grow. cbn [fb_begin fb_end].
    assert (AO' : exists L', LB' = (p', A', fb_newsize FB n) :: L' /\ aobj L' LF a k).
    { destruct ALT as [[_ ->]|(p & INp & ->)]; eexists; (split; [reflexivity|]); [exact AO|].
      destruct AO as [(b & Hb & H1 & H2)|K]; [left| right; exact K]. exists b. split; [| split; assumption].
      apply (ah_lb_remove_keep H HH); [exact (ah_nodup H HH _ _ _ RH)| exact Hb|].
      intros E. pose proof (nodup_blk_eq _ _ _ (ah_nodup H HH _ _ _ RH) Hb INp E) as EB. subst b. cbn [blk_addr blk_size fst snd] in H1, H2.
      unfold fb_cap in H2. lia. }
    destruct AO' as (L' & -> & AO'). split; [apply aobj_cons; exact AO'|].
    pose proof (fresh_vs_aobj H HH _ _ _ _ _ _ _ _ _ _ RH' RF AO' Hk). lia.
  Qed.
